            Click(Button(chat,"ShellAvatar"));await Task.Delay(30);menu=Button(chat,"ShellAvatar").ContextMenu;menu.Items.OfType<MenuItem>().Single(i=>i.Name=="ProfileUsage").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));await Task.Delay(100);Save(chat,"app-shell-usage.png");
            Click(Button(chat,"ShellHome"));await Task.Delay(50);chat.Width=700;await Task.Delay(70);Click(Button(chat,"ToggleAppSidebar"));await Task.Delay(50);Check(All<FrameworkElement>(chat).Any(e=>e.Name=="AgentWorkspaceSidebar"&&e.IsVisible)&&rail.IsVisible,"narrow width can temporarily open project navigation without hiding the rail");
